window.PORTABLE_CSS_TEXT = "/* main.css - نظام التصميم والأنماط لنظام المحاسبة المتقدم (يعمل 100% أوفلاين بدون أي اتصال بالإنترنت) */\n\n:root {\n    /* لوحة الألوان المحاسبية الاحترافية */\n    --primary: #1e3a8a;          /* أزرق مالي عميق */\n    --primary-light: #3b82f6;    /* أزرق تفاعلي */\n    --primary-dark: #172554;\n    --primary-bg: #eff6ff;\n    \n    --success: #059669;          /* أخضر مالي للأرباح والدائن */\n    --success-light: #10b981;\n    --success-bg: #ecfdf5;\n    \n    --danger: #dc2626;           /* أحمر للمصروفات والفرق */\n    --danger-light: #ef4444;\n    --danger-bg: #fef2f2;\n    \n    --warning: #d97706;          /* كهرماني للتنبيهات */\n    --warning-bg: #fffbeb;\n    \n    --info: #0284c7;\n    --info-bg: #f0f9ff;\n\n    /* تدرجات الرمادي والأسطح */\n    --bg-main: #f8fafc;\n    --bg-surface: #ffffff;\n    --bg-surface-elevated: #ffffff;\n    --bg-alt: #f1f5f9;\n    \n    --text-primary: #0f172a;\n    --text-secondary: #475569;\n    --text-muted: #64748b;\n    --text-inverse: #ffffff;\n    \n    --border-color: #e2e8f0;\n    --border-dark: #cbd5e1;\n    \n    /* المتغيرات الهيكلية - خطوط النظام المحلية السريعة للعمل أوفلاين */\n    --font-family: 'Cairo', 'Segoe UI', Tahoma, system-ui, -apple-system, sans-serif;\n    --radius-sm: 6px;\n    --radius-md: 10px;\n    --radius-lg: 16px;\n    --radius-xl: 20px;\n    \n    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);\n    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);\n    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.05);\n    \n    --sidebar-width: 270px;\n    --header-height: 70px;\n    --transition-fast: 0.15s ease;\n    --transition-normal: 0.25s ease;\n}\n\n/* إعادة الضبط والقيم الأساسية */\n*, *::before, *::after {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n}\n\nbody {\n    font-family: var(--font-family);\n    background-color: var(--bg-main);\n    color: var(--text-primary);\n    direction: rtl;\n    text-align: right;\n    line-height: 1.6;\n    font-size: 14.5px;\n    min-height: 100vh;\n    display: flex;\n    overflow-x: hidden;\n}\n\n/* تخطيط التطبيق الرئيسي */\n.app-container {\n    display: flex;\n    width: 100%;\n    max-width: 100%;\n    min-height: 100vh;\n}\n\n/* الشريط الجانبي للتنقل */\n.sidebar {\n    width: var(--sidebar-width);\n    background-color: var(--primary-dark);\n    color: #e2e8f0;\n    display: flex;\n    flex-direction: column;\n    position: fixed;\n    top: 0;\n    bottom: 0;\n    right: 0;\n    z-index: 50;\n    box-shadow: -2px 0 12px rgba(0, 0, 0, 0.15);\n    transition: transform var(--transition-normal);\n}\n\n.brand-section {\n    padding: 24px 20px;\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n}\n\n.brand-icon {\n    width: 44px;\n    height: 44px;\n    background: linear-gradient(135deg, #3b82f6, #1d4ed8);\n    border-radius: var(--radius-md);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-size: 22px;\n    box-shadow: 0 4px 10px rgba(59, 130, 246, 0.4);\n}\n\n.brand-info h1 {\n    font-size: 17px;\n    font-weight: 700;\n    color: #ffffff;\n    letter-spacing: -0.2px;\n}\n\n.brand-info span {\n    font-size: 11.5px;\n    color: #94a3b8;\n    display: block;\n}\n\n/* قائمة التنقل */\n.nav-menu {\n    flex: 1;\n    padding: 16px 12px;\n    list-style: none;\n    overflow-y: auto;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n}\n\n.nav-item-btn {\n    width: 100%;\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 11px 16px;\n    background: transparent;\n    border: none;\n    border-radius: var(--radius-md);\n    color: #cbd5e1;\n    font-family: inherit;\n    font-size: 14px;\n    font-weight: 500;\n    cursor: pointer;\n    text-align: right;\n    transition: all var(--transition-fast);\n}\n\n.nav-item-btn:hover {\n    background-color: rgba(255, 255, 255, 0.08);\n    color: #ffffff;\n}\n\n.nav-item-btn.active {\n    background: #2563eb;\n    color: #ffffff;\n    font-weight: 600;\n    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35);\n}\n\n.nav-icon {\n    font-size: 18px;\n    width: 24px;\n    text-align: center;\n}\n\n.nav-badge {\n    margin-right: auto;\n    font-size: 11px;\n    padding: 2px 8px;\n    border-radius: 12px;\n    background: rgba(255, 255, 255, 0.15);\n    font-weight: 600;\n}\n\n.sidebar-footer {\n    padding: 16px;\n    border-top: 1px solid rgba(255, 255, 255, 0.1);\n    display: flex;\n    flex-direction: column;\n    gap: 10px;\n}\n\n.system-status {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    font-size: 12px;\n    color: #94a3b8;\n}\n\n.status-dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    background-color: var(--success-light);\n    box-shadow: 0 0 8px var(--success-light);\n}\n\n/* المنطقة الرئيسية للمحتوى */\n.main-wrapper {\n    flex: 1;\n    min-width: 0;\n    width: calc(100% - var(--sidebar-width));\n    max-width: calc(100% - var(--sidebar-width));\n    margin-right: var(--sidebar-width);\n    display: flex;\n    flex-direction: column;\n    min-height: 100vh;\n    background-color: var(--bg-main);\n}\n\n/* الشريط العلوي */\n.top-header {\n    min-height: var(--header-height);\n    height: auto;\n    background-color: var(--bg-surface);\n    border-bottom: 1px solid var(--border-color);\n    padding: 10px 24px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    flex-wrap: wrap;\n    gap: 12px;\n    position: sticky;\n    top: 0;\n    z-index: 40;\n}\n\n.header-title-area h2 {\n    font-size: 18px;\n    font-weight: 700;\n    color: var(--text-primary);\n}\n\n.header-title-area p {\n    font-size: 12px;\n    color: var(--text-muted);\n}\n\n.header-actions {\n    display: flex;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 8px;\n}\n\n.header-actions .btn {\n    padding: 7px 12px;\n    font-size: 12.5px;\n    white-space: nowrap;\n}\n\n/* الأزرار العامة */\n.btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: 8px;\n    padding: 9px 18px;\n    font-family: inherit;\n    font-size: 13.5px;\n    font-weight: 600;\n    border-radius: var(--radius-md);\n    border: 1px solid transparent;\n    cursor: pointer;\n    transition: all var(--transition-fast);\n    text-decoration: none;\n    line-height: 1.2;\n}\n\n.btn-primary {\n    background-color: var(--primary);\n    color: #ffffff;\n}\n\n.btn-primary:hover {\n    background-color: var(--primary-light);\n    box-shadow: 0 4px 12px rgba(30, 58, 138, 0.25);\n}\n\n.btn-success {\n    background-color: var(--success);\n    color: #ffffff;\n}\n\n.btn-success:hover {\n    background-color: var(--success-light);\n    box-shadow: 0 4px 12px rgba(5, 150, 105, 0.25);\n}\n\n.btn-danger {\n    background-color: var(--danger);\n    color: #ffffff;\n}\n\n.btn-danger:hover {\n    background-color: var(--danger-light);\n}\n\n.btn-outline {\n    background-color: var(--bg-surface);\n    border-color: var(--border-dark);\n    color: var(--text-secondary);\n}\n\n.btn-outline:hover {\n    background-color: var(--bg-alt);\n    color: var(--text-primary);\n    border-color: #94a3b8;\n}\n\n.btn-sm {\n    padding: 6px 12px;\n    font-size: 12.5px;\n    border-radius: var(--radius-sm);\n}\n\n/* مساحة المحتوى والشاشات */\n.content-area {\n    padding: 22px 24px;\n    flex: 1;\n    min-width: 0;\n    max-width: 100%;\n}\n\n.tab-pane {\n    display: none;\n    min-width: 0;\n    max-width: 100%;\n    animation: fadeIn 0.25s ease forwards;\n}\n\n.tab-pane.active {\n    display: block;\n}\n\n@keyframes fadeIn {\n    from { opacity: 0; transform: translateY(6px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n/* بطاقات الإحصائيات المطورة (Dashboard KPI Cards) */\n.metrics-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n    gap: 16px;\n    margin-bottom: 24px;\n}\n\n.metric-card {\n    position: relative;\n    background: linear-gradient(145deg, #ffffff 0%, #f8fafc 100%);\n    border: 1px solid rgba(226, 232, 240, 0.9);\n    border-radius: 18px;\n    padding: 18px 16px;\n    min-width: 0;\n    box-shadow: 0 8px 24px -6px rgba(15, 23, 42, 0.06), 0 2px 6px -1px rgba(15, 23, 42, 0.04);\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    overflow: hidden;\n    transition: transform 0.25s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.metric-card::before {\n    content: '';\n    position: absolute;\n    top: 0;\n    right: 0;\n    left: 0;\n    height: 4px;\n    background: linear-gradient(90deg, #3b82f6, #1d4ed8);\n    border-radius: 18px 18px 0 0;\n}\n\n.metric-card::after {\n    content: '';\n    position: absolute;\n    width: 110px;\n    height: 110px;\n    border-radius: 50%;\n    top: -35px;\n    left: -35px;\n    background: radial-gradient(circle, rgba(59, 130, 246, 0.08) 0%, transparent 70%);\n    pointer-events: none;\n}\n\n.metric-card.accent-blue::before { background: linear-gradient(90deg, #2563eb, #60a5fa); }\n.metric-card.accent-amber::before { background: linear-gradient(90deg, #d97706, #fbbf24); }\n.metric-card.accent-emerald::before { background: linear-gradient(90deg, #059669, #34d399); }\n.metric-card.accent-teal::before { background: linear-gradient(90deg, #0d9488, #2dd4bf); }\n.metric-card.accent-red::before { background: linear-gradient(90deg, #dc2626, #f87171); }\n.metric-card.accent-purple::before { background: linear-gradient(90deg, #7c3aed, #c084fc); }\n\n.metric-card:hover {\n    transform: translateY(-5px);\n    box-shadow: 0 16px 32px -8px rgba(15, 23, 42, 0.12), 0 4px 12px -2px rgba(15, 23, 42, 0.06);\n    border-color: #cbd5e1;\n}\n\n.metric-icon {\n    width: 58px;\n    height: 58px;\n    border-radius: 16px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 26px;\n    flex-shrink: 0;\n    position: relative;\n    z-index: 1;\n    transition: transform 0.25s ease;\n}\n\n.metric-card:hover .metric-icon {\n    transform: scale(1.08) rotate(-3deg);\n}\n\n.metric-icon.blue {\n    background: linear-gradient(135deg, #2563eb, #1d4ed8);\n    color: #ffffff;\n    box-shadow: 0 8px 16px -4px rgba(37, 99, 235, 0.4);\n}\n.metric-icon.green {\n    background: linear-gradient(135deg, #10b981, #059669);\n    color: #ffffff;\n    box-shadow: 0 8px 16px -4px rgba(5, 150, 105, 0.4);\n}\n.metric-icon.teal {\n    background: linear-gradient(135deg, #14b8a6, #0d9488);\n    color: #ffffff;\n    box-shadow: 0 8px 16px -4px rgba(13, 148, 136, 0.4);\n}\n.metric-icon.amber {\n    background: linear-gradient(135deg, #f59e0b, #d97706);\n    color: #ffffff;\n    box-shadow: 0 8px 16px -4px rgba(217, 119, 6, 0.4);\n}\n.metric-icon.red {\n    background: linear-gradient(135deg, #ef4444, #dc2626);\n    color: #ffffff;\n    box-shadow: 0 8px 16px -4px rgba(220, 38, 38, 0.4);\n}\n.metric-icon.purple {\n    background: linear-gradient(135deg, #8b5cf6, #6d28d9);\n    color: #ffffff;\n    box-shadow: 0 8px 16px -4px rgba(124, 58, 237, 0.4);\n}\n\n.metric-content {\n    flex: 1;\n    overflow: hidden;\n    position: relative;\n    z-index: 1;\n}\n\n.metric-label {\n    font-size: 13px;\n    font-weight: 700;\n    color: #475569;\n    margin-bottom: 6px;\n}\n\n.metric-value {\n    font-size: 22px;\n    font-weight: 900;\n    color: #0f172a;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    letter-spacing: -0.3px;\n}\n\n.metric-sub {\n    font-size: 11.5px;\n    font-weight: 600;\n    color: #64748b;\n    margin-top: 6px;\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n    background: #f1f5f9;\n    padding: 3px 9px;\n    border-radius: 20px;\n}\n\n.metric-sub.positive {\n    color: #047857;\n    background: #ecfdf5;\n}\n.metric-sub.negative {\n    color: #b91c1c;\n    background: #fef2f2;\n}\n\n/* البطاقات الحاوية للأقسام */\n.card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-lg);\n    box-shadow: var(--shadow-sm);\n    margin-bottom: 24px;\n    min-width: 0;\n    max-width: 100%;\n    overflow: hidden;\n}\n\n.card-header {\n    padding: 16px 20px;\n    border-bottom: 1px solid var(--border-color);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    flex-wrap: wrap;\n    gap: 12px;\n    background-color: #fafbfc;\n}\n\n.card-header h3 {\n    font-size: 16px;\n    font-weight: 700;\n    color: var(--text-primary);\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.card-body {\n    padding: 18px 20px;\n    min-width: 0;\n    max-width: 100%;\n}\n\n/* شريط الفلاتر والبحث */\n.filter-bar {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: 14px;\n    margin-bottom: 20px;\n    background: var(--bg-alt);\n    padding: 14px 18px;\n    border-radius: var(--radius-md);\n}\n\n.filter-group {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.filter-group label {\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--text-secondary);\n    white-space: nowrap;\n}\n\n/* عناصر الإدخال والنماذج */\n.input-control, .select-control {\n    font-family: inherit;\n    font-size: 13.5px;\n    padding: 8px 14px;\n    border: 1px solid var(--border-dark);\n    border-radius: var(--radius-sm);\n    background-color: var(--bg-surface);\n    color: var(--text-primary);\n    outline: none;\n    transition: border-color var(--transition-fast), box-shadow var(--transition-fast);\n}\n\n.input-control:focus, .select-control:focus {\n    border-color: var(--primary-light);\n    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);\n}\n\n.search-input {\n    min-width: 260px;\n}\n\n/* الجداول المحاسبية القياسية */\n.table-responsive {\n    width: 100%;\n    max-width: 100%;\n    overflow-x: auto;\n    border-radius: var(--radius-md);\n    border: 1px solid var(--border-color);\n}\n\n.acc-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 13px;\n    background: var(--bg-surface);\n}\n\n.acc-table th {\n    background-color: #f1f5f9;\n    color: var(--text-secondary);\n    font-weight: 700;\n    padding: 10px 10px;\n    text-align: right;\n    border-bottom: 2px solid var(--border-color);\n    white-space: nowrap;\n}\n\n.acc-table td {\n    padding: 10px 10px;\n    border-bottom: 1px solid var(--border-color);\n    color: var(--text-primary);\n    vertical-align: middle;\n}\n\n.acc-table tr:last-child td {\n    border-bottom: none;\n}\n\n.acc-table tbody tr:hover {\n    background-color: #f8fafc;\n}\n\n.acc-table th.num, .acc-table td.num {\n    text-align: left;\n    direction: ltr;\n    font-family: monospace, sans-serif;\n    font-weight: 600;\n}\n\n.acc-table tfoot td {\n    background-color: #f8fafc;\n    font-weight: 800;\n    border-top: 2px solid var(--border-dark);\n    padding: 14px 16px;\n}\n\n/* شارات التصنيف والحالة */\n.badge {\n    display: inline-block;\n    padding: 4px 10px;\n    border-radius: 12px;\n    font-size: 12px;\n    font-weight: 600;\n    white-space: nowrap;\n}\n\n.badge-asset { background: #eff6ff; color: #1d4ed8; }\n.badge-liability { background: #fff7ed; color: #c2410c; }\n.badge-equity { background: #faf5ff; color: #6b21a8; }\n.badge-revenue { background: #ecfdf5; color: #047857; }\n.badge-expense { background: #fef2f2; color: #b91c1c; }\n\n.badge-debit { background: #eff6ff; color: #1e40af; }\n.badge-credit { background: #ecfdf5; color: #065f46; }\n\n/* شاشة إدخال القيد اليومي المزدوج */\n.entry-form-header {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n    gap: 16px;\n    background: #f8fafc;\n    padding: 18px;\n    border-radius: var(--radius-md);\n    margin-bottom: 20px;\n    border: 1px solid var(--border-color);\n}\n\n.form-group {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n}\n\n.form-group label {\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--text-secondary);\n}\n\n.form-group label .req {\n    color: var(--danger);\n}\n\n.entry-lines-table {\n    margin-bottom: 16px;\n}\n\n.entry-lines-table input, .entry-lines-table select {\n    width: 100%;\n}\n\n.entry-balance-checker {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 16px 20px;\n    background: #f1f5f9;\n    border-radius: var(--radius-md);\n    border: 1px solid var(--border-color);\n    margin-bottom: 20px;\n}\n\n.balance-indicators {\n    display: flex;\n    gap: 24px;\n    align-items: center;\n}\n\n.balance-box {\n    display: flex;\n    flex-direction: column;\n}\n\n.balance-box span:first-child {\n    font-size: 12px;\n    color: var(--text-muted);\n}\n\n.balance-box .amount {\n    font-size: 16px;\n    font-weight: 700;\n}\n\n.balance-status {\n    padding: 8px 16px;\n    border-radius: var(--radius-md);\n    font-weight: 700;\n    font-size: 13.5px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.balance-status.balanced {\n    background-color: var(--success-bg);\n    color: var(--success);\n    border: 1px solid rgba(5, 150, 105, 0.2);\n}\n\n.balance-status.unbalanced {\n    background-color: var(--danger-bg);\n    color: var(--danger);\n    border: 1px solid rgba(220, 38, 38, 0.2);\n}\n\n/* النوافذ المنبثقة (Modals) */\n.modal-overlay {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background-color: rgba(15, 23, 42, 0.6);\n    backdrop-filter: blur(4px);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 100;\n    opacity: 0;\n    visibility: hidden;\n    transition: all var(--transition-normal);\n    padding: 20px;\n}\n\n.modal-overlay.active {\n    opacity: 1;\n    visibility: visible;\n}\n\n.modal-box {\n    background: var(--bg-surface);\n    border-radius: var(--radius-xl);\n    width: 100%;\n    max-width: 750px;\n    max-height: 90vh;\n    display: flex;\n    flex-direction: column;\n    box-shadow: var(--shadow-xl);\n    transform: scale(0.95);\n    transition: transform var(--transition-normal);\n    overflow: hidden;\n}\n\n.modal-overlay.active .modal-box {\n    transform: scale(1);\n}\n\n.modal-box.modal-lg {\n    max-width: 950px;\n}\n\n.modal-header {\n    padding: 18px 24px;\n    border-bottom: 1px solid var(--border-color);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    background-color: #fafbfc;\n}\n\n.modal-header h3 {\n    font-size: 17px;\n    font-weight: 700;\n}\n\n.modal-close-btn {\n    background: transparent;\n    border: none;\n    font-size: 20px;\n    color: var(--text-muted);\n    cursor: pointer;\n    padding: 4px;\n    border-radius: 4px;\n    line-height: 1;\n}\n\n.modal-close-btn:hover {\n    color: var(--danger);\n    background: #f1f5f9;\n}\n\n.modal-body {\n    padding: 24px;\n    overflow-y: auto;\n}\n\n.modal-footer {\n    padding: 16px 24px;\n    border-top: 1px solid var(--border-color);\n    display: flex;\n    align-items: center;\n    justify-content: flex-end;\n    gap: 12px;\n    background-color: #fafbfc;\n}\n\n/* إشعارات التنبيه (Toast Notifications) */\n.toast-container {\n    position: fixed;\n    bottom: 24px;\n    left: 24px;\n    z-index: 999;\n    display: flex;\n    flex-direction: column;\n    gap: 10px;\n}\n\n.toast {\n    background: var(--bg-surface);\n    border-radius: var(--radius-md);\n    padding: 14px 20px;\n    box-shadow: var(--shadow-lg);\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    font-size: 13.5px;\n    font-weight: 600;\n    animation: slideUp 0.3s ease forwards;\n    border-right: 4px solid var(--primary);\n    min-width: 280px;\n}\n\n.toast.success { border-right-color: var(--success); color: #065f46; background: #f0fdf4; }\n.toast.error { border-right-color: var(--danger); color: #991b1b; background: #fef2f2; }\n.toast.info { border-right-color: var(--info); color: #075985; background: #f0f9ff; }\n\n@keyframes slideUp {\n    from { opacity: 0; transform: translateY(20px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n/* سند القيد المحاسبي والتقارير للطباعة والمعاينة */\n.voucher-paper {\n    background: #ffffff;\n    padding: 30px;\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-md);\n    margin-bottom: 20px;\n}\n\n.voucher-header {\n    text-align: center;\n    border-bottom: 2px solid #0f172a;\n    padding-bottom: 18px;\n    margin-bottom: 20px;\n}\n\n.voucher-header h2 {\n    font-size: 22px;\n    font-weight: 800;\n    color: #0f172a;\n    margin-bottom: 4px;\n}\n\n.voucher-header .sub-title {\n    font-size: 15px;\n    color: var(--text-secondary);\n    font-weight: 600;\n}\n\n.voucher-meta-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 12px;\n    margin-bottom: 20px;\n    background: #f8fafc;\n    padding: 14px;\n    border-radius: var(--radius-sm);\n    font-size: 13.5px;\n}\n\n.voucher-meta-item strong {\n    color: var(--text-secondary);\n}\n\n.voucher-signatures {\n    margin-top: 40px;\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    text-align: center;\n    padding-top: 20px;\n    border-top: 1px dashed var(--border-dark);\n}\n\n.sig-box {\n    display: flex;\n    flex-direction: column;\n    gap: 35px;\n}\n\n.sig-box span {\n    font-weight: 600;\n    color: var(--text-secondary);\n}\n\n/* تنسيقات مركز طباعة الفواتير الاحترافي */\n.print-center-layout {\n    display: grid;\n    grid-template-columns: 320px 1fr;\n    gap: 24px;\n    align-items: start;\n}\n\n.print-inv-item {\n    padding: 12px 14px;\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-md);\n    margin-bottom: 8px;\n    cursor: pointer;\n    background: #ffffff;\n    transition: all 0.2s ease;\n}\n\n.print-inv-item:hover {\n    border-color: #93c5fd;\n    background: #f8fafc;\n}\n\n.print-inv-item.active {\n    border-color: var(--primary);\n    background: #eff6ff;\n    box-shadow: 0 4px 12px rgba(30, 58, 138, 0.1);\n}\n\n.invoice-pro-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    border-bottom: 3px solid var(--primary);\n    padding-bottom: 18px;\n    margin-bottom: 20px;\n}\n\n.invoice-type-ribbon {\n    display: inline-block;\n    padding: 6px 16px;\n    border-radius: 8px;\n    font-weight: 800;\n    font-size: 13.5px;\n    color: #ffffff;\n}\n\n.invoice-type-ribbon.sales {\n    background: linear-gradient(135deg, #059669, #10b981);\n}\n\n.invoice-type-ribbon.purchase {\n    background: linear-gradient(135deg, #1e3a8a, #3b82f6);\n}\n\n/* قالب الفاتورة الحرارية 80mm */\n.thermal-receipt-paper {\n    width: 340px;\n    margin: 0 auto;\n    background: #ffffff;\n    border: 1px solid #cbd5e1;\n    border-radius: 8px;\n    padding: 20px 16px;\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);\n    font-size: 12.5px;\n    color: #0f172a;\n}\n\n.thermal-header {\n    text-align: center;\n    border-bottom: 1px dashed #64748b;\n    padding-bottom: 10px;\n    margin-bottom: 10px;\n}\n\n.thermal-header h2 {\n    font-size: 16px;\n    font-weight: 800;\n    margin-bottom: 3px;\n}\n\n.thermal-title-box {\n    text-align: center;\n    font-weight: 800;\n    font-size: 14px;\n    background: #f1f5f9;\n    padding: 5px;\n    border-radius: 4px;\n    margin-bottom: 10px;\n}\n\n.thermal-meta {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    border-bottom: 1px dashed #64748b;\n    padding-bottom: 10px;\n    margin-bottom: 10px;\n}\n\n.thermal-meta div {\n    display: flex;\n    justify-content: space-between;\n}\n\n.thermal-table {\n    width: 100%;\n    border-collapse: collapse;\n    margin-bottom: 10px;\n    font-size: 12px;\n}\n\n.thermal-table th {\n    border-bottom: 1px solid #0f172a;\n    padding: 5px 2px;\n    text-align: right;\n}\n\n.thermal-table td {\n    padding: 6px 2px;\n    border-bottom: 1px dotted #cbd5e1;\n}\n\n.thermal-totals {\n    border-top: 1px dashed #0f172a;\n    padding-top: 8px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n}\n\n.thermal-totals .row {\n    display: flex;\n    justify-content: space-between;\n}\n\n.thermal-totals .row.grand {\n    font-size: 15px;\n    font-weight: 900;\n    border-top: 1px solid #0f172a;\n    padding-top: 6px;\n    margin-top: 4px;\n}\n\n.thermal-footer {\n    margin-top: 14px;\n    padding-top: 10px;\n    border-top: 1px dashed #64748b;\n    text-align: center;\n    font-size: 11.5px;\n    color: #475569;\n}\n\n/* تنسيقات الطباعة الرسمية */\n@media print {\n    body {\n        background: #ffffff !important;\n        color: #000000 !important;\n        font-size: 12pt;\n    }\n\n    .sidebar, .top-header, .filter-bar, .no-print, .btn, .toast-container, .print-center-sidebar {\n        display: none !important;\n    }\n\n    .print-center-layout {\n        display: block !important;\n    }\n\n    .main-wrapper {\n        margin-right: 0 !important;\n        padding: 0 !important;\n    }\n\n    .content-area {\n        padding: 0 !important;\n    }\n\n    .card {\n        border: none !important;\n        box-shadow: none !important;\n    }\n\n    .voucher-paper, .thermal-receipt-paper {\n        border: none !important;\n        box-shadow: none !important;\n        padding: 0 !important;\n    }\n\n    .acc-table th, .invoice-type-ribbon {\n        -webkit-print-color-adjust: exact;\n        print-color-adjust: exact;\n    }\n}\n\n/* التجاوب مع شاشات الجوال والأجهزة اللوحية */\n@media (max-width: 992px) {\n    .sidebar {\n        transform: translateX(100%);\n    }\n\n    .sidebar.open {\n        transform: translateX(0);\n    }\n\n    .main-wrapper {\n        margin-right: 0;\n        width: 100%;\n        max-width: 100%;\n    }\n\n    .top-header {\n        padding: 0 16px;\n    }\n\n    .content-area {\n        padding: 20px 16px;\n    }\n\n    .menu-toggle-btn {\n        display: block !important;\n    }\n}\n\n.menu-toggle-btn {\n    display: none;\n    background: transparent;\n    border: none;\n    font-size: 24px;\n    cursor: pointer;\n    color: var(--text-primary);\n}\n\n/* ==================== تصميم الفاتورة العصرية وكليشة الفاتورة ==================== */\n.inv-sheet {\n    --inv-accent: #1e3a8a;\n    --inv-accent-dark: #11235a;\n    --inv-accent-soft: rgba(30, 58, 138, 0.08);\n    --inv-accent-mid: rgba(30, 58, 138, 0.18);\n    position: relative;\n    width: 100%;\n    max-width: 820px;\n    margin: 0 auto;\n    background: #ffffff;\n    color: #0f172a;\n    font-size: 13px;\n    border-radius: 14px;\n    overflow: hidden;\n    box-shadow: 0 20px 50px -12px rgba(15, 23, 42, 0.18), 0 0 0 1px rgba(15, 23, 42, 0.06);\n}\n\n.inv-sheet *, .thermal-receipt-paper * {\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n}\n\n.inv-header {\n    position: relative;\n    overflow: hidden;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 20px;\n    padding: 28px 34px;\n}\n\n.inv-header-modern {\n    background: linear-gradient(135deg, var(--inv-accent) 0%, var(--inv-accent-dark) 100%);\n    color: #ffffff;\n}\n\n.inv-header-modern::before {\n    content: '';\n    position: absolute;\n    width: 260px;\n    height: 260px;\n    border-radius: 50%;\n    background: rgba(255, 255, 255, 0.07);\n    top: -120px;\n    left: -70px;\n}\n\n.inv-header-modern::after {\n    content: '';\n    position: absolute;\n    width: 200px;\n    height: 200px;\n    border-radius: 50%;\n    background: rgba(255, 255, 255, 0.05);\n    bottom: -110px;\n    right: 28%;\n}\n\n.inv-header-classic {\n    background: #ffffff;\n    color: #0f172a;\n    border-bottom: 4px solid var(--inv-accent);\n}\n\n.inv-header-minimal {\n    background: #ffffff;\n    color: #0f172a;\n    flex-direction: column;\n    text-align: center;\n    border-bottom: 1px solid #e2e8f0;\n}\n\n.inv-header-minimal .inv-brand { flex-direction: column; }\n.inv-header-minimal .inv-contact { justify-content: center; }\n.inv-header-minimal .inv-doc { text-align: center; }\n\n.inv-brand {\n    position: relative;\n    z-index: 1;\n    display: flex;\n    align-items: center;\n    gap: 16px;\n}\n\n.inv-logo {\n    width: 72px;\n    height: 72px;\n    flex-shrink: 0;\n    border-radius: 18px;\n    background: #ffffff;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n    padding: 6px;\n    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.18);\n}\n\n.inv-header-classic .inv-logo,\n.inv-header-minimal .inv-logo {\n    box-shadow: 0 0 0 1px #e2e8f0;\n}\n\n.inv-logo img {\n    max-width: 100%;\n    max-height: 100%;\n    object-fit: contain;\n}\n\n.inv-logo-mono {\n    font-size: 36px;\n    font-weight: 900;\n    color: var(--inv-accent);\n}\n\n.inv-brand-text h1 {\n    font-size: 22px;\n    font-weight: 900;\n    letter-spacing: -0.3px;\n    margin: 0 0 2px;\n}\n\n.inv-slogan {\n    font-size: 12.5px;\n    font-weight: 600;\n    opacity: 0.88;\n    margin-bottom: 6px;\n}\n\n.inv-header-classic .inv-slogan,\n.inv-header-minimal .inv-slogan {\n    color: var(--inv-accent);\n    opacity: 1;\n}\n\n.inv-contact {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px 14px;\n    font-size: 11.5px;\n    opacity: 0.92;\n}\n\n.inv-doc {\n    position: relative;\n    z-index: 1;\n    text-align: left;\n}\n\n.inv-doc-title {\n    font-size: 25px;\n    font-weight: 900;\n}\n\n.inv-doc-en {\n    font-size: 11px;\n    font-weight: 700;\n    letter-spacing: 2.5px;\n    opacity: 0.8;\n    margin-top: 2px;\n}\n\n.inv-doc-no {\n    display: inline-block;\n    margin-top: 8px;\n    padding: 4px 14px;\n    border-radius: 30px;\n    font-family: monospace;\n    font-size: 13.5px;\n    font-weight: 800;\n    background: rgba(255, 255, 255, 0.2);\n}\n\n.inv-header-classic .inv-doc-title,\n.inv-header-minimal .inv-doc-title {\n    color: var(--inv-accent);\n}\n\n.inv-header-classic .inv-doc-no,\n.inv-header-minimal .inv-doc-no {\n    background: var(--inv-accent-soft);\n    color: var(--inv-accent);\n}\n\n.inv-banner img {\n    display: block;\n    width: 100%;\n}\n\n.inv-title-strip {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 12px 34px;\n    background: linear-gradient(135deg, var(--inv-accent), var(--inv-accent-dark));\n    color: #ffffff;\n}\n\n.inv-title-strip .t strong {\n    font-size: 17px;\n    font-weight: 900;\n    margin-left: 10px;\n}\n\n.inv-title-strip .t span {\n    font-size: 11px;\n    letter-spacing: 2px;\n    opacity: 0.8;\n    font-weight: 700;\n}\n\n.inv-title-strip .n {\n    font-family: monospace;\n    font-size: 15px;\n    font-weight: 800;\n    background: rgba(255, 255, 255, 0.2);\n    padding: 3px 14px;\n    border-radius: 30px;\n}\n\n.inv-body {\n    padding: 26px 34px 8px;\n}\n\n.inv-info-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 14px;\n}\n\n.inv-info-card {\n    border: 1px solid #e2e8f0;\n    border-right: 4px solid var(--inv-accent);\n    border-radius: 12px;\n    padding: 13px 16px;\n    background: #ffffff;\n}\n\n.inv-info-title {\n    font-size: 11px;\n    font-weight: 800;\n    letter-spacing: 0.5px;\n    color: var(--inv-accent);\n    margin-bottom: 6px;\n}\n\n.inv-party {\n    font-size: 17px;\n    font-weight: 800;\n    margin-bottom: 6px;\n}\n\n.inv-info-line {\n    display: flex;\n    justify-content: space-between;\n    gap: 10px;\n    padding: 3px 0;\n    font-size: 12.5px;\n    color: #475569;\n}\n\n.inv-info-line strong {\n    color: #0f172a;\n}\n\n.inv-table {\n    width: 100%;\n    margin: 20px 0 16px;\n    border-collapse: separate;\n    border-spacing: 0;\n    border: 1px solid #e2e8f0;\n    border-radius: 12px;\n    overflow: hidden;\n}\n\n.inv-table thead th {\n    background: var(--inv-accent);\n    color: #ffffff;\n    padding: 11px 12px;\n    font-size: 12px;\n    font-weight: 700;\n    text-align: right;\n}\n\n.inv-table td {\n    padding: 11px 12px;\n    border-bottom: 1px solid #eef2f7;\n    font-size: 12.5px;\n}\n\n.inv-table tbody tr:nth-child(even) td {\n    background: #f8fafc;\n}\n\n.inv-table tbody tr:last-child td {\n    border-bottom: none;\n}\n\n.inv-table .c { text-align: center; }\n.inv-table .num { text-align: left; font-variant-numeric: tabular-nums; }\n\n.inv-sku {\n    font-family: monospace;\n    font-size: 11px;\n    color: #94a3b8;\n    margin-top: 2px;\n}\n\n.inv-bottom {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 24px;\n    flex-wrap: wrap;\n}\n\n.inv-notes-col {\n    flex: 1;\n    min-width: 220px;\n}\n\n.inv-note-box {\n    background: var(--inv-accent-soft);\n    border-right: 3px solid var(--inv-accent);\n    border-radius: 10px;\n    padding: 10px 14px;\n    font-size: 12.5px;\n    color: #334155;\n}\n\n.inv-note-box strong {\n    display: block;\n    color: var(--inv-accent);\n    margin-bottom: 3px;\n}\n\n.inv-stamp {\n    display: inline-block;\n    margin-top: 16px;\n    padding: 4px 22px;\n    border: 3px solid;\n    border-radius: 10px;\n    font-size: 20px;\n    font-weight: 900;\n    letter-spacing: 1px;\n    transform: rotate(-7deg);\n    opacity: 0.85;\n}\n\n.inv-stamp.paid { color: #059669; border-color: #059669; }\n.inv-stamp.unpaid { color: #d97706; border-color: #d97706; }\n\n.inv-totals {\n    width: 300px;\n    border: 1px solid #e2e8f0;\n    border-radius: 12px;\n    overflow: hidden;\n}\n\n.inv-totals .r {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 10px 16px;\n    font-size: 13px;\n    border-bottom: 1px solid #eef2f7;\n}\n\n.inv-totals .r.disc { color: #dc2626; }\n\n.inv-totals .r.grand {\n    border-bottom: none;\n    background: linear-gradient(135deg, var(--inv-accent), var(--inv-accent-dark));\n    color: #ffffff;\n    font-size: 16px;\n    font-weight: 900;\n    padding: 13px 16px;\n}\n\n.inv-sigs {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 26px;\n    margin: 38px 0 18px;\n}\n\n.inv-sig {\n    border-top: 1.5px dashed #94a3b8;\n    padding-top: 8px;\n    text-align: center;\n    font-size: 12px;\n    font-weight: 700;\n    color: #475569;\n}\n\n.inv-footer {\n    margin-top: 18px;\n    padding: 13px 20px;\n    text-align: center;\n    font-size: 12.5px;\n    font-weight: 700;\n    color: #ffffff;\n    background: linear-gradient(135deg, var(--inv-accent), var(--inv-accent-dark));\n}\n\n.thermal-logo {\n    display: block;\n    width: 56px;\n    height: 56px;\n    object-fit: contain;\n    margin: 0 auto 6px;\n}\n\n/* لوحة تخصيص الكليشة */\n.brand-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n    gap: 22px;\n}\n\n.brand-block {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n}\n\n.brand-label {\n    font-size: 13px;\n    font-weight: 700;\n    color: var(--text-secondary);\n}\n\n.brand-preview-box {\n    height: 92px;\n    border: 2px dashed var(--border-dark);\n    border-radius: var(--radius-md);\n    background: #f8fafc;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    padding: 8px;\n    overflow: hidden;\n}\n\n.brand-actions {\n    display: flex;\n    gap: 8px;\n    flex-wrap: wrap;\n}\n\n.brand-hint {\n    font-size: 11.5px;\n    color: var(--text-muted);\n}\n\n.brand-swatches {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n}\n\n.brand-swatch {\n    width: 30px;\n    height: 30px;\n    border-radius: 50%;\n    border: 3px solid #ffffff;\n    box-shadow: 0 0 0 1px #cbd5e1;\n    cursor: pointer;\n    transition: transform 0.15s ease;\n}\n\n.brand-swatch:hover { transform: scale(1.12); }\n.brand-swatch.active { box-shadow: 0 0 0 3px #0f172a; }\n\n.brand-color-input {\n    width: 44px;\n    height: 34px;\n    padding: 0;\n    border: 1px solid var(--border-dark);\n    border-radius: 8px;\n    background: #ffffff;\n    cursor: pointer;\n}\n\n.print-center-preview-wrapper {\n    overflow-x: auto;\n    padding: 4px;\n}\n\n@media (max-width: 700px) {\n    .inv-info-grid { grid-template-columns: 1fr; }\n    .inv-header { flex-direction: column; text-align: center; }\n    .inv-doc { text-align: center; }\n}\n\n@media print {\n    @page { margin: 8mm; }\n\n    .inv-sheet {\n        box-shadow: none !important;\n        border-radius: 0 !important;\n        max-width: none !important;\n    }\n\n    /* طباعة النوافذ المنبثقة (معاينة الفاتورة / السند) بشكل نظيف */\n    body:has(.modal-overlay.active) .app-container {\n        display: none !important;\n    }\n\n    .modal-overlay.active {\n        position: static !important;\n        display: block !important;\n        background: transparent !important;\n        backdrop-filter: none !important;\n        padding: 0 !important;\n        overflow: visible !important;\n    }\n\n    .modal-overlay.active .modal-box {\n        box-shadow: none !important;\n        border: none !important;\n        max-height: none !important;\n        max-width: none !important;\n        width: 100% !important;\n    }\n\n    .modal-overlay.active .modal-header,\n    .modal-overlay.active .modal-footer {\n        display: none !important;\n    }\n}\n";
window.__PORTABLE_APP_INIT_JS__ = "// app.js - نقطة البداية والتشغيل والربط الشامل للنظام المحاسبي والمخزني\n\ndocument.addEventListener('DOMContentLoaded', () => {\n    console.log('✨ جاري تشغيل نظام المحاسبة وإدارة المخزون المتقدم...');\n    \n    // تسجيل الـ Service Worker للعمل أوفلاين\n    if ('serviceWorker' in navigator) {\n        window.addEventListener('load', () => {\n            navigator.serviceWorker.register('./sw.js')\n                .then(reg => console.log('✅ تم تفعيل التشغيل أوفلاين (Service Worker Ready):', reg.scope))\n                .catch(err => console.log('⚠️ تعذر تسجيل Service Worker:', err));\n        });\n    }\n\n    // تهيئة واجهة المستخدم\n    ui.init();\n\n    // ==================== نماذج المحاسبة ====================\n    const entryForm = document.getElementById('entry-form');\n    if (entryForm) {\n        entryForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveEntryFromForm();\n        });\n    }\n\n    const accountForm = document.getElementById('account-form');\n    if (accountForm) {\n        accountForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveAccountFromForm();\n        });\n    }\n\n    const settingsForm = document.getElementById('settings-form');\n    if (settingsForm) {\n        settingsForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveSettingsFromForm();\n        });\n    }\n\n    const passwordSettingsForm = document.getElementById('password-settings-form');\n    if (passwordSettingsForm) {\n        passwordSettingsForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.savePasswordFromForm();\n        });\n    }\n\n    const passwordConfirmForm = document.getElementById('password-confirm-form');\n    if (passwordConfirmForm) {\n        passwordConfirmForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.confirmPasswordAction();\n        });\n    }\n\n    // ==================== نماذج المخزون ====================\n    const productForm = document.getElementById('product-form');\n    if (productForm) {\n        productForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveProductFromForm();\n        });\n    }\n\n    const warehouseForm = document.getElementById('warehouse-form');\n    if (warehouseForm) {\n        warehouseForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveWarehouseFromForm();\n        });\n    }\n\n    const transferForm = document.getElementById('transfer-form');\n    if (transferForm) {\n        transferForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveTransferFromForm();\n        });\n    }\n\n    const adjustmentForm = document.getElementById('adjustment-form');\n    if (adjustmentForm) {\n        adjustmentForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveAdjustmentFromForm();\n        });\n    }\n\n    const stockInForm = document.getElementById('stock-in-form');\n    if (stockInForm) {\n        stockInForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveStockInFromForm();\n        });\n    }\n\n    const invoiceForm = document.getElementById('invoice-form');\n    if (invoiceForm) {\n        invoiceForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveInvoiceFromForm();\n        });\n    }\n\n    const openingBatchForm = document.getElementById('opening-batch-form');\n    if (openingBatchForm) {\n        openingBatchForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveOpeningBatchFromForm();\n        });\n    }\n\n    const voucherForm = document.getElementById('voucher-form');\n    if (voucherForm) {\n        voucherForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveVoucherFromForm();\n        });\n    }\n\n    const partyForm = document.getElementById('party-form');\n    if (partyForm) {\n        partyForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.savePartyFromForm();\n        });\n    }\n\n    const quotationForm = document.getElementById('quotation-form');\n    if (quotationForm) {\n        quotationForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveQuotationFromForm();\n        });\n    }\n\n    const expenseForm = document.getElementById('expense-form');\n    if (expenseForm) {\n        expenseForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveExpenseFromForm();\n        });\n    }\n\n    const installmentForm = document.getElementById('installment-form');\n    if (installmentForm) {\n        installmentForm.addEventListener('submit', (e) => {\n            e.preventDefault();\n            ui.saveInstallmentFromForm();\n        });\n    }\n\n    // ==================== أحداث الفلاتر للفواتير ====================\n    const invSearch = document.getElementById('invoice-search');\n    if (invSearch) invSearch.addEventListener('input', () => ui.renderInvoices());\n\n    const invTypeFilter = document.getElementById('invoice-type-filter');\n    if (invTypeFilter) invTypeFilter.addEventListener('change', () => ui.renderInvoices());\n\n    const invPayFilter = document.getElementById('invoice-pay-filter');\n    if (invPayFilter) invPayFilter.addEventListener('change', () => ui.renderInvoices());\n\n    // ==================== أحداث الفلاتر للمنتجات ====================\n    const prodSearch = document.getElementById('products-search');\n    if (prodSearch) prodSearch.addEventListener('input', () => ui.renderProducts());\n\n    const prodCatFilter = document.getElementById('products-category-filter');\n    if (prodCatFilter) prodCatFilter.addEventListener('change', () => ui.renderProducts());\n\n    // ==================== أحداث حركات المخزون والتحويل ====================\n    const stockSearch = document.getElementById('stock-ops-search');\n    if (stockSearch) stockSearch.addEventListener('input', () => ui.renderStockOps());\n\n    const stockTypeFilter = document.getElementById('stock-ops-type-filter');\n    if (stockTypeFilter) stockTypeFilter.addEventListener('change', () => ui.renderStockOps());\n\n    const trFromWh = document.getElementById('tr-from-wh');\n    if (trFromWh) trFromWh.addEventListener('change', () => ui.updateTransferAvailableStock());\n\n    const trProd = document.getElementById('tr-product');\n    if (trProd) trProd.addEventListener('change', () => ui.updateTransferAvailableStock());\n\n    const adjProd = document.getElementById('adj-prod');\n    if (adjProd) adjProd.addEventListener('change', () => ui.onAdjustmentProductSelect());\n\n    const adjWh = document.getElementById('adj-wh');\n    if (adjWh) adjWh.addEventListener('change', () => ui.onAdjustmentProductSelect());\n\n    const inProd = document.getElementById('in-prod');\n    if (inProd) inProd.addEventListener('change', () => ui.onStockInProductSelect());\n\n    // ==================== أحداث تقارير المخزون ====================\n    document.querySelectorAll('input[name=\"inv-report-sub\"]').forEach(radio => {\n        radio.addEventListener('change', (e) => ui.showSubReport(e.target.value));\n    });\n\n    const invRepWhFilter = document.getElementById('inv-rep-wh-filter');\n    if (invRepWhFilter) invRepWhFilter.addEventListener('change', () => ui.renderInventoryReports());\n\n    const invRepProdSelect = document.getElementById('inv-rep-prod-select');\n    if (invRepProdSelect) invRepProdSelect.addEventListener('change', () => ui.showSubReport('item_card'));\n\n    const invRepDateFrom = document.getElementById('inv-rep-date-from');\n    if (invRepDateFrom) invRepDateFrom.addEventListener('change', () => ui.showSubReport('item_card'));\n\n    const invRepDateTo = document.getElementById('inv-rep-date-to');\n    if (invRepDateTo) invRepDateTo.addEventListener('change', () => ui.showSubReport('item_card'));\n\n    // ==================== فلاتر الحسابات والقيود والتقارير المالية ====================\n    const accSearch = document.getElementById('accounts-search');\n    if (accSearch) accSearch.addEventListener('input', () => ui.renderAccounts());\n\n    const accTypeFilter = document.getElementById('accounts-type-filter');\n    if (accTypeFilter) accTypeFilter.addEventListener('change', () => ui.renderAccounts());\n\n    const entrySearch = document.getElementById('entries-search');\n    if (entrySearch) entrySearch.addEventListener('input', () => ui.renderEntries());\n\n    const entryDateFrom = document.getElementById('entries-date-from');\n    if (entryDateFrom) entryDateFrom.addEventListener('change', () => ui.renderEntries());\n\n    const entryDateTo = document.getElementById('entries-date-to');\n    if (entryDateTo) entryDateTo.addEventListener('change', () => ui.renderEntries());\n\n    const ledgerAccSelect = document.getElementById('ledger-account-select');\n    if (ledgerAccSelect) ledgerAccSelect.addEventListener('change', () => ui.renderLedger());\n\n    const ledgerDateFrom = document.getElementById('ledger-date-from');\n    if (ledgerDateFrom) ledgerDateFrom.addEventListener('change', () => ui.renderLedger());\n\n    const ledgerDateTo = document.getElementById('ledger-date-to');\n    if (ledgerDateTo) ledgerDateTo.addEventListener('change', () => ui.renderLedger());\n\n    const tbDateFrom = document.getElementById('tb-date-from');\n    if (tbDateFrom) tbDateFrom.addEventListener('change', () => ui.renderTrialBalance());\n\n    const tbDateTo = document.getElementById('tb-date-to');\n    if (tbDateTo) tbDateTo.addEventListener('change', () => ui.renderTrialBalance());\n\n    document.querySelectorAll('input[name=\"report-type\"]').forEach(radio => {\n        radio.addEventListener('change', () => ui.renderReports());\n    });\n\n    const reportDateTo = document.getElementById('report-date-to');\n    if (reportDateTo) reportDateTo.addEventListener('change', () => ui.renderReports());\n\n    // تعيين التاريخ الافتراضي\n    const today = new Date().toISOString().split('T')[0];\n    if (reportDateTo && !reportDateTo.value) reportDateTo.value = today;\n    if (tbDateTo && !tbDateTo.value) tbDateTo.value = today;\n\n    console.log('✅ تم تشغيل النظام بنجاح وتجهيز كافة السجلات المحاسبية والمخزنية.');\n});\n";
